scripts:
const slides=[...document.querySelectorAll('.slide')];let idx=0;
const thaiSlideGuides=[{"title": "Application Layer", "read": "บทนี้อธิบายชั้นแอปพลิเคชัน ซึ่งเป็นชั้นที่ผู้ใช้มองเห็นผ่านเว็บ อีเมล การโอนถ่ายไฟล์ และแอปออนไลน์ต่าง ๆ จุดสำคัญคือโปรแกรมเหล่านี้ต้องใช้โปรโตคอลร่วมกัน เช่น HTTP, DNS, FTP, SMTP, IMAP และ POP3 เพื่อให้เครื่องต้นทางและปลายทางเข้าใจข้อความตรงกัน", "talk": "สไลด์นี้เป็นภาพรวมของบทที่ 3 ค่ะ เราจะเรียนว่าการเปิดเว็บ ส่งอีเมล หรือดาวน์โหลดไฟล์ เกิดขึ้นได้เพราะโปรแกรมใช้โปรโตคอลของชั้นแอปพลิเคชัน ไม่ใช่แค่มีอินเทอร์เน็ตแล้วข้อมูลจะเข้าใจกันเอง"}, {"title": "Application Layer อยู่ตรงไหน", "read": "Application Layer อยู่บนสุดของ TCP/IP 5-layer model ทำหน้าที่กำหนดความหมายและรูปแบบข้อความของบริการ เช่น เว็บ อีเมล DNS และการโอนถ่ายไฟล์ ส่วนชั้นล่างรับผิดชอบการขนส่ง การหาเส้นทาง เฟรม และสัญญาณจริง", "talk": "หน้านี้ให้จำว่า Application Layer อยู่บนสุดค่ะ ชั้นนี้ไม่ได้ส่งบิตเอง แต่กำหนดว่า message หมายถึงอะไร เช่น HTTP request หรือ DNS query ส่วนชั้นล่างช่วยพาข้อมูลไปถึงปลายทาง"}, {"title": "Application กับ Protocol", "read": "Application คือโปรแกรมที่ผู้ใช้ใช้งาน เช่น browser หรือ email client ส่วน protocol คือกติกาที่โปรแกรมใช้สื่อสารกัน หนึ่ง application อาจใช้หลาย protocol เช่น email client ใช้ SMTP ตอนส่ง และใช้ IMAP หรือ POP3 ตอนอ่าน", "talk": "หน้านี้แยก application กับ protocol ค่ะ Chrome เป็น application แต่ HTTP เป็น protocol ส่วนโปรแกรมอีเมลหนึ่งตัวอาจใช้หลาย protocol ดังนั้นอย่าจำว่าแอปหนึ่งตัวเท่ากับโปรโตคอลหนึ่งตัวเสมอไป"}, {"title": "Architecture types", "read": "Network application architecture อธิบายบทบาทของเครื่องหรือ process ในระบบ รูปแบบหลักคือ client–server, peer-to-peer และ hybrid โดย client–server มี server กลาง, peer-to-peer ให้แต่ละ peer ช่วยให้บริการ และ hybrid ผสมสองแนวคิดเข้าด้วยกัน", "talk": "หน้านี้ดูรูปแบบสถาปัตยกรรมค่ะ แบบ client–server ควบคุมง่าย แบบ peer-to-peer กระจายงานมากกว่า และ hybrid ใช้ server ช่วยบางอย่างแต่ยังมีการส่งข้อมูลระหว่าง peer ได้"}, {"title": "Processes communicating", "read": "ในการสื่อสารบนเครือข่าย สิ่งที่สื่อสารกันจริงคือ process หรือโปรแกรมที่กำลังทำงานอยู่ ไม่ใช่เครื่องทั้งเครื่อง เครื่องหนึ่งมีหลาย process จึงต้องใช้ port number ระบุว่าข้อมูลควรถูกส่งให้บริการใด", "talk": "หน้านี้เน้นคำว่า process ค่ะ เวลา browser คุยกับ web server จริง ๆ คือ browser process คุยกับ server process และ port number จะบอกว่าข้อมูลนี้ควรไปที่ service ไหน"}, {"title": "Socket overview", "read": "Socket คือจุดเชื่อมต่อระหว่าง application process กับ transport layer โปรแกรมใช้ socket เพื่อส่งและรับข้อมูล โดยต้องระบุปลายทางด้วย IP address และ port number", "talk": "ให้มอง socket เป็นประตูที่โปรแกรมใช้เข้าออกเครือข่ายค่ะ โปรแกรมเขียนข้อมูลผ่าน socket แล้วระบบปฏิบัติการกับ TCP/IP stack จะช่วยส่งข้อมูลต่อไป"}, {"title": "Socket workflow", "read": "ฝั่ง server มักสร้าง socket, bind กับ port, listen, accept แล้วจึงรับส่งข้อมูล ส่วนฝั่ง client สร้าง socket และ connect ไปยัง IP กับ port ของ server จากนั้นจึงสื่อสารกันได้", "talk": "หน้านี้เป็นขั้นตอนการเขียนโปรแกรม socket ค่ะ server เปิดรอ ส่วน client connect เข้าไป เมื่อเชื่อมต่อสำเร็จทั้งสองฝั่งจึง send และ receive ข้อมูลได้"}, {"title": "Ports and services", "read": "IP address ใช้หา host ปลายทาง ส่วน port number ใช้หา service หรือ process ภายใน host นั้น ตัวอย่างเช่น IP พาไปถึง server แต่ port 443 บอกว่าเป็นบริการ HTTPS", "talk": "จุดสำคัญคือ IP หาเครื่อง ส่วน port หาบริการค่ะ ถ้าไม่มี port เครื่องปลายทางจะไม่รู้ว่าข้อมูลนี้ต้องส่งให้โปรแกรมไหนจัดการ"}, {"title": "DNS purpose", "read": "DNS แปลงชื่อโดเมนที่มนุษย์จำง่าย เช่น www.example.com ให้เป็น IP address ที่เครื่องใช้สื่อสารจริง ถ้าไม่มี DNS ผู้ใช้ต้องจำตัวเลข IP จำนวนมาก", "talk": "หน้านี้อธิบายหน้าที่ของ DNS ค่ะ เราจำชื่อเว็บ แต่เครื่องต้องใช้ IP ดังนั้น DNS ช่วยแปลชื่อให้เป็น IP ก่อน browser จะเชื่อมต่อได้"}, {"title": "DNS resolution", "read": "DNS resolution คือกระบวนการค้นหา IP address จากชื่อโดเมน โดย client ถาม recursive resolver และ resolver อาจไปถาม root, TLD และ authoritative server จนได้คำตอบ แล้วมัก cache ไว้ใช้ครั้งต่อไป", "talk": "ให้ดูว่า client ไม่ได้ถามทุก server เองค่ะ ส่วนใหญ่ถาม recursive resolver แล้ว resolver ไปค้นต่อจนได้ IP ส่งกลับมา และ cache ช่วยให้ครั้งถัดไปเร็วขึ้น"}, {"title": "What is HTTP", "read": "HTTP คือโปรโตคอลของเว็บที่กำหนดรูปแบบ request และ response ระหว่าง browser กับ web server เช่น client ส่ง GET เพื่อขอ resource และ server ตอบกลับด้วย status code, headers และ body", "talk": "หน้านี้เข้าสู่ HTTP ค่ะ HTTP คือกติกาที่ browser กับ server ใช้คุยกัน ไม่ใช่หน้าเว็บเอง แต่เป็นวิธีขอและตอบข้อมูลของเว็บ"}, {"title": "HTTP request-response", "read": "HTTP ทำงานแบบ request–response โดย client เริ่มส่งคำขอ และ server ตอบกลับ คำขอมี method, path, headers และอาจมี body ส่วนคำตอบมี status code, headers และ body", "talk": "หน้านี้ให้จำว่า client เป็นฝ่ายเริ่มก่อนเสมอค่ะ ส่ง request ไป แล้ว server ส่ง response กลับมา เช่นสำเร็จคือ 200 OK หรือไม่พบหน้าคือ 404 Not Found"}, {"title": "State vs Stateless HTTP", "read": "HTTP โดยตัวมันเองเป็น stateless protocol คือแต่ละ request เป็นอิสระ Server ไม่จำ request ก่อนหน้าโดยอัตโนมัติ แต่เว็บแอปต้องมี state เช่น login, cart, preference จึงใช้ cookie, session ID, token หรือ JWT เพื่อจำผู้ใช้", "talk": "หน้านี้สำคัญมากค่ะ HTTP ไม่จำเราเอง ถ้าเว็บต้องรู้ว่าเรา login แล้ว ต้องมี cookie, session หรือ token แนบไปกับ request เพื่อให้ server รู้ว่าเป็นผู้ใช้คนเดิม"}, {"title": "Non-persistent vs Persistent HTTP", "read": "Non-persistent HTTP เปิด TCP connection ใหม่สำหรับแต่ละ object ทำให้ overhead สูง ส่วน persistent HTTP ใช้ connection เดิมส่งหลาย request/response ต่อเนื่องกัน ลดเวลาและเพิ่มประสิทธิภาพ", "talk": "หน้านี้เปรียบเทียบการใช้ connection ค่ะ non-persistent ขอหนึ่ง object แล้วปิด แต่ persistent ใช้ connection เดิมขอหลาย object ได้ จึงเหมาะกับหน้าเว็บที่มีหลายไฟล์"}, {"title": "HTTP version transition", "read": "HTTP พัฒนาจาก HTTP/0.9 ที่เรียบง่าย ไปสู่ HTTP/1.0 ที่มี headers และ status codes, HTTP/1.1 ที่เน้น persistent connection, HTTP/2 ที่มี multiplexing และ HTTP/3 ที่ใช้ QUIC บน UDP เพื่อลด latency", "talk": "หน้านี้คือพัฒนาการของ HTTP ค่ะ แนวคิด request–response ยังอยู่ แต่เวอร์ชันใหม่เพิ่มประสิทธิภาพ เช่น connection reuse, multiplexing และ QUIC"}, {"title": "HTTP methods", "read": "HTTP method บอกว่า client ต้องการให้ server ทำอะไรกับ resource เช่น GET ขอข้อมูล, POST ส่งข้อมูลหรือสร้างข้อมูล, PUT/PATCH อัปเดต และ DELETE ลบข้อมูล", "talk": "หน้านี้อธิบาย method ค่ะ method คือกริยาของ HTTP ถ้าเราเลือก method ถูก API จะอ่านง่ายและสื่อความหมายตรง เช่น GET เพื่ออ่าน POST เพื่อส่งข้อมูล"}, {"title": "URL anatomy", "read": "URL ใช้ระบุตำแหน่งของ resource บนเว็บ ประกอบด้วย scheme เช่น https, host, path, query string และบางครั้งมี port หรือ fragment URL จึงบอกทั้งวิธีติดต่อ host และ resource ที่ต้องการ", "talk": "หน้านี้แยกส่วน URL ค่ะ https คือ scheme, domain คือ host, path คือ resource และ query คือข้อมูลเพิ่มเติมที่ส่งไปกับ URL"}, {"title": "HTTP status codes", "read": "Status code คือรหัสผลลัพธ์ใน HTTP response เลขหลักแรกบอกประเภท เช่น 2xx สำเร็จ, 3xx redirect, 4xx ปัญหาจาก client เช่น 404 Not Found และ 5xx ปัญหาจาก server เช่น 500 Internal Server Error", "talk": "หน้านี้ดู status code ค่ะ ให้ดูเลขตัวแรกก่อน 2 สำเร็จ 3 เปลี่ยนเส้นทาง 4 ปัญหาฝั่ง client และ 5 ปัญหาฝั่ง server ตัวอย่างที่พบบ่อยคือ 404"}, {"title": "HTTPS and TLS", "read": "HTTPS คือ HTTP ที่ถูกป้องกันด้วย TLS โดย HTTP ยังเป็น request–response เหมือนเดิม แต่ TLS เพิ่มการเข้ารหัส ความถูกต้องของข้อมูล และการตรวจสอบตัวตนของ server ก่อนส่งผ่าน TCP/IP โดยทั่วไปใช้ port 443", "talk": "หน้านี้ต้องจำว่า HTTPS ไม่ได้แทนที่ HTTP ค่ะ แต่คือ HTTP over TLS ข้อความ HTTP ยังมีอยู่ เพียงแต่ถูก TLS ป้องกันก่อนส่งผ่าน TCP/IP"}, {"title": "FTP file transfer", "read": "FTP ใช้โอนถ่ายไฟล์ระหว่าง client และ server โดยแยก control channel สำหรับคำสั่งและรหัสตอบกลับ กับ data channel สำหรับส่งไฟล์จริง FTP ดั้งเดิมไม่เข้ารหัส จึงควรใช้ FTPS หรือ SFTP เมื่อมีข้อมูลสำคัญ", "talk": "หน้านี้เป็น FTP ค่ะ จุดสำคัญคือ control channel ส่งคำสั่ง เช่น USER, PASS, RETR, STOR ส่วน data channel ส่งไฟล์จริง และ FTP แบบเดิมไม่ปลอดภัย"}, {"title": "Email protocols", "read": "ระบบอีเมลใช้หลายโปรโตคอลร่วมกัน ผู้ส่งใช้ SMTP submission ส่งจาก MUA ไป mail server จากนั้น server ใช้ DNS MX หา receiver mail server แล้วส่งต่อด้วย SMTP relay ผู้รับใช้ IMAP หรือ POP3 อ่าน mailbox", "talk": "หน้านี้อธิบาย email flow ค่ะ ส่งอีเมลใช้ SMTP, หา server ปลายทางด้วย DNS MX แล้วผู้รับอ่านกล่องจดหมายด้วย IMAP หรือ POP3"}, {"title": "Other protocols", "read": "Application Layer ยังมีโปรโตคอลอื่น เช่น DHCP แจก IP configuration, SSH ใช้ remote login แบบปลอดภัย, SNMP ใช้มอนิเตอร์อุปกรณ์, NTP ใช้ซิงก์เวลา และ MQTT ใช้สื่อสารแบบ lightweight ใน IoT", "talk": "หน้านี้ให้เห็นว่า Application Layer ไม่ได้มีแค่เว็บกับอีเมลค่ะ แต่มีหลายโปรโตคอลที่แก้ปัญหาคนละแบบ เช่น DHCP, SSH, SNMP, NTP และ MQTT"}, {"title": "Choose a protocol", "read": "การเลือกโปรโตคอลต้องดูงานที่ต้องการทำ เช่น เปิดเว็บใช้ HTTP/HTTPS, แปลงชื่อใช้ DNS, ส่งอีเมลใช้ SMTP, อ่านอีเมลใช้ IMAP/POP3 และโอนถ่ายไฟล์ใช้ FTP/FTPS/SFTP", "talk": "หน้านี้เป็นกิจกรรมค่ะ ให้เริ่มจากถามว่างานคืออะไร แล้วเลือกโปรโตคอลให้ตรง เช่น เปิดเว็บคือ HTTP หรือ HTTPS และส่งอีเมลคือ SMTP"}, {"title": "Protocol matching", "read": "แบบฝึกหัดจับคู่ช่วยทบทวนหน้าที่ของโปรโตคอล เช่น HTTP สำหรับเว็บ, DNS สำหรับแปลงชื่อ, SMTP สำหรับส่งอีเมล, IMAP/POP3 สำหรับอ่านอีเมล, FTP สำหรับโอนถ่ายไฟล์ และ SSH สำหรับ remote login", "talk": "หน้าสุดท้ายเป็นการทบทวนค่ะ ให้นักศึกษาจับคู่ protocol กับ service เพื่อเช็คว่าเข้าใจภาพรวมของ application layer จริงหรือไม่"}];
thaiSlideGuides.push({title:'คู่มือทบทวนภาษาไทยทุกสไลด์',read:'สไลด์สุดท้ายเป็นคู่มือทบทวนภาษาไทยสำหรับนักศึกษา นักศึกษาสามารถเลือกหมายเลขสไลด์เพื่ออ่านเนื้อหาสรุปแบบละเอียด พร้อมภาพประกอบหรือภาพจำของแต่ละหัวข้อ และสามารถพิมพ์เป็นเอกสารกลับไปทบทวนหลังเรียนได้',talk:'สไลด์นี้เป็นหน้ารวมสำหรับทบทวนค่ะ นักศึกษาสามารถเลือกสไลด์ที่ต้องการอ่านเนื้อหาภาษาไทย ดูภาพประกอบ และใช้ปุ่ม Print เพื่อเก็บเป็นเอกสารทบทวนได้'});
