slides.forEach((s,i)=>{const sec=s.dataset.section||'Section';if(sec!==lastSection){if(topicRanges.length)topicRanges[topicRanges.length-1].end=i-1;topicRanges.push({section:sec,start:i,end:slides.length-1});const div=document.createElement('div');div.className='tocSection';div.textContent=conciseSectionLabels[sec]||sec;toc.appendChild(div);lastSection=sec}const b=document.createElement('button');b.className='tocItem';const slideLabel=conciseSlideLabels[s.dataset.title]||s.dataset.title;b.innerHTML=`<span class="tocNum">${i+1}</span><span class="tocText">${slideLabel}</span>`;b.onclick=()=>go(i);toc.appendChild(b)});
