const extraThaiGuideByTitle = {"DNS hierarchy and records": {"title": "DNS hierarchy and records", "read": "DNS เป็นระบบลำดับชั้น ประกอบด้วย root, TLD, authoritative server และ recursive resolver ข้อมูลถูกเก็บเป็น record หลายชนิด เช่น A, AAAA, CNAME, MX, NS, PTR, TXT และ SRV โดย TTL กำหนดระยะเวลาที่ cache ใช้คำตอบเดิมได้", "talk": "หน้านี้ให้แยกสามเรื่องค่ะ คือโครงสร้างลำดับชั้น บทบาทของ server และชนิดของ record ส่วน recursive resolver เป็นผู้ค้นหาแทน client และเก็บ cache ไว้ตามค่า TTL"}, "DHCP lease lifecycle": {"title": "DHCP lease lifecycle", "read": "DHCP แจกค่าตั้งเครือข่ายด้วยกระบวนการ DORA: Discover, Offer, Request และ Acknowledge หลังได้รับ lease เครื่องจะเข้าสู่ BOUND และพยายามต่ออายุที่ T1 ถ้าไม่สำเร็จจะเข้าสู่ REBINDING ที่ T2 และต้องหยุดใช้ address เมื่อ lease หมดอายุ", "talk": "ให้จำ DORA ก่อนค่ะ จากนั้นดูว่า address ไม่ได้ให้ถาวรแต่เป็น lease มีเวลา เมื่อถึง T1 จะขอต่ออายุกับ server เดิม และเมื่อถึง T2 จะถาม server ใดก็ได้"}, "DHCP relay and DNS": {"title": "DHCP relay and DNS", "read": "DHCP broadcast ปกติข้าม router ไม่ได้ จึงใช้ relay agent ส่งคำขอไปยัง DHCP server ที่อยู่อีก subnet หนึ่ง DHCP สามารถแจก address ของ DNS resolver ให้ client ส่วน DNS ทำหน้าที่แปลงชื่อ บางองค์กรอาจใช้ Dynamic DNS เพื่ออัปเดตชื่อเมื่อ lease เปลี่ยน", "talk": "หน้านี้แยกหน้าที่ค่ะ relay ช่วยส่ง DHCP ข้าม subnet, DHCP แจก DNS server address และ DNS ใช้แก้ชื่อ ส่วน DDNS เป็นคุณสมบัติเพิ่มเติม ไม่ได้เกิดอัตโนมัติในทุกระบบ"}, "HTTP headers and content types": {"title": "HTTP headers and content types", "read": "HTTP message มี start line, headers, บรรทัดว่าง และ body ที่อาจมีหรือไม่มีก็ได้ Headers บอกข้อมูลควบคุม เช่น Host, Accept, Authorization, Content-Type, Content-Length, Set-Cookie และ Cache-Control", "talk": "หน้านี้อ่าน HTTP message เป็นส่วน ๆ ค่ะ บรรทัดแรกบอก request หรือผลลัพธ์ headers อธิบาย metadata และหลังบรรทัดว่างจึงเป็น body"}, "Cookies and sessions": {"title": "Cookies and sessions", "read": "HTTP เป็น stateless แต่เว็บแอปสร้างความต่อเนื่องด้วย cookie, session หรือ token Server อาจส่ง Set-Cookie แล้ว browser ส่ง Cookie กลับใน request ถัดไป ควรใช้ Secure, HttpOnly และ SameSite เพื่อลดความเสี่ยง", "talk": "ให้จำว่า cookie เป็นตัวพา identifier ค่ะ ส่วน state จริงอาจอยู่ที่ server หรืออยู่ใน token ที่ป้องกันแล้ว ไม่ควรเก็บ password แบบ plaintext ใน cookie"}, "HTTP caching and proxies": {"title": "HTTP caching and proxies", "read": "Cache เก็บ response เพื่อนำกลับมาใช้ ลดเวลาและปริมาณข้อมูล สามารถตรวจสอบความสดด้วย ETag หรือ Last-Modified และ server อาจตอบ 304 Not Modified Proxy มีทั้ง forward proxy ที่ทำงานแทน client และ reverse proxy ที่อยู่หน้า server", "talk": "หน้านี้ให้ดูว่า 304 หมายถึงใช้ body ใน cache เดิมได้ค่ะ ส่วน forward proxy อยู่ฝั่ง client และ reverse proxy อยู่หน้า server เช่น load balancer หรือ CDN"}, "Common application services": {"title": "Common application services", "read": "บริการชั้นแอปพลิเคชันมีหลายกลุ่ม เช่น SMTP/IMAP/POP3 สำหรับอีเมล, FTP/SFTP สำหรับไฟล์, SSH/RDP สำหรับ remote access, LDAP สำหรับ directory และ NTP สำหรับเวลา ควรเลือกแบบเข้ารหัสเมื่อมีข้อมูลสำคัญ", "talk": "หน้านี้ไม่ต้องจำ port ทุกตัวค่ะ ให้จำหน้าที่ของบริการและแยกตัวเลือกปลอดภัย เช่น SSH แทน Telnet และ SFTP หรือ FTPS แทน FTP ธรรมดา"}, "Message formats and service discovery": {"title": "Message formats and service discovery", "read": "Protocol ต้องกำหนดรูปแบบข้อมูล เช่น JSON, XML หรือ binary รวมทั้งวิธีแบ่งขอบเขต message, content type, state และ session การค้นหาบริการอาจใช้ DNS A/AAAA, MX, SRV, mDNS หรือ service registry", "talk": "หน้านี้เน้นว่า protocol ไม่ได้มีแค่ชื่อค่ะ ต้องบอกทั้งรูปแบบ message ความหมาย ลำดับการส่ง และวิธีหา service ปลายทาง"}, "Packet capture workflow": {"title": "Packet capture workflow", "read": "การอ่าน packet capture ควรเริ่มจากระบุ endpoint และ filter ให้แคบ จากนั้นหา request แรก จับคู่ response ตาม field ของ protocol สร้างลำดับ state และใช้ status, error หรือ timing อธิบายผล", "talk": "อย่าอ่านทีละ packet แบบแยกกันค่ะ ให้มองเป็นบทสนทนาและเริ่มจาก dependency เช่น DHCP และ DNS ก่อน HTTP"}, "Interpret protocol exchanges": {"title": "Interpret protocol exchanges", "read": "HTTP ดู method และ status, DNS ดู transaction ID และ record, DHCP ดู DORA กับ lease options, email ดู command/reply และ remote access ดูการเจรจาและการเข้ารหัส HTTPS, SSH และ RDP อาจไม่เห็น payload ภายใน", "talk": "หน้านี้ใช้ปุ่มเลือก protocol แล้วสังเกตว่าแต่ละบริการมีลำดับและ field สำคัญต่างกันค่ะ เป้าหมายคืออธิบายสิ่งที่ capture พิสูจน์ได้จริง"}};
