function escapeHTML(str){const div=document.createElement('div');div.textContent=String(str||'');return div.innerHTML;}
function thaiParagraphs(str){return String(str||'').split(/\n+/).filter(Boolean).map(p=>`<p>${escapeHTML(p)}</p>`).join('');}
function guideFor(i){const title=slides[i]?.dataset.title||`Slide ${i+1}`;return thaiGuideByTitle[title]||{title,read:'กำลังเตรียมเนื้อหาภาษาไทยสำหรับสไลด์นี้',talk:'กำลังเตรียมบทพูดภาษาไทยสำหรับสไลด์นี้'};}
function openThaiPanel(mode){
 const g=guideFor(idx);const panel=document.getElementById('thaiPanel');
 document.getElementById('thaiPanelMode').textContent=mode==='talk'?'บทพูดภาษาไทย':'เนื้อหาอ่านภาษาไทย';
 document.getElementById('thaiPanelTitle').textContent=`Slide ${idx+1}: ${g.title}`;
 document.getElementById('thaiPanelBody').innerHTML=thaiParagraphs(mode==='talk'?g.talk:g.read);
 panel.classList.add('open');
}
function buildPrintNotes(){slides.forEach((s,i)=>{s.querySelectorAll('.printOnly,.thaiPrintBlock').forEach(el=>el.remove());const g=guideFor(i);const panel=document.createElement('div');panel.className='thaiPrintBlock';panel.innerHTML=`<h3>Slide ${i+1}: ${escapeHTML(g.title)}</h3><h4>เนื้อหาอ่านภาษาไทย</h4>${thaiParagraphs(g.read)}<h4>บทพูดภาษาไทย</h4>${thaiParagraphs(g.talk)}`;s.appendChild(panel);});}
buildPrintNotes();

function thaiReviewIcon(title,i){
 const t=String(title||'').toLowerCase();
 if(t.includes('dhcp'))return '📡';
 if(t.includes('capture')||t.includes('exchange'))return '🔎';
 if(t.includes('directory')||t.includes('service discovery'))return '🗂️';
 if(t.includes('dns'))return '🧭';
 if(t.includes('http')&&t.includes('version'))return '🕰️';
 if(t.includes('http')||t.includes('status')||t.includes('url'))return '🌐';
 if(t.includes('state')||t.includes('stateless'))return '🍪';
 if(t.includes('persistent'))return '🔁';
 if(t.includes('https')||t.includes('tls'))return '🔐';
 if(t.includes('ftp')||t.includes('file'))return '📁';
 if(t.includes('email')||t.includes('mail'))return '✉️';
 if(t.includes('socket')||t.includes('port'))return '🔌';
 if(t.includes('protocol matching')||t.includes('choose'))return '✅';
 if(t.includes('architecture'))return '🏗️';
 if(t.includes('process'))return '⚙️';
 if(t.includes('application'))return '🧩';
 return ['📘','💻','🖥️','📡','🔗'][i%5];
}
function thaiReviewKey(title){
 const t=String(title||'').toLowerCase();
 if(t.includes('dhcp'))return 'จำหลัก: DHCP แจกค่าตั้งเครือข่ายแบบ lease และอาจใช้ relay agent เพื่อข้าม subnet';
 if(t.includes('capture')||t.includes('exchange'))return 'จำหลัก: อ่าน packet capture เป็นบทสนทนา โดยจับคู่ request กับ response และใช้ field เป็นหลักฐาน';
 if(t.includes('dns'))return 'จำหลัก: DNS ใช้ hierarchy, typed records, resolver, authoritative server และ cache เพื่อแปลงชื่อ';
 if(t.includes('stateless'))return 'จำหลัก: HTTP ไม่จำผู้ใช้เอง จึงต้องใช้ cookie, session หรือ token เพื่อสร้าง state';
 if(t.includes('persistent'))return 'จำหลัก: persistent connection ลดการเปิด TCP connection ซ้ำหลายครั้ง';
 if(t.includes('status'))return 'จำหลัก: ดูเลขหลักแรกของ status code เพื่อรู้ประเภทผลลัพธ์';
 if(t.includes('https'))return 'จำหลัก: HTTPS คือ HTTP ที่ถูกป้องกันด้วย TLS แล้วจึงส่งผ่าน TCP/IP';
 if(t.includes('ftp'))return 'จำหลัก: FTP แยก control channel สำหรับคำสั่ง และ data channel สำหรับไฟล์จริง';
 if(t.includes('email'))return 'จำหลัก: SMTP ใช้ส่งอีเมล ส่วน IMAP/POP3 ใช้อ่าน mailbox';
 if(t.includes('socket'))return 'จำหลัก: socket คือจุดที่โปรแกรมใช้ส่งและรับข้อมูลผ่าน transport layer';
 if(t.includes('port'))return 'จำหลัก: IP หาเครื่อง ส่วน port หาบริการหรือ process ในเครื่องนั้น';
 if(t.includes('url'))return 'จำหลัก: URL บอก scheme, host, path และข้อมูลเสริมของ resource';
 return 'จำหลัก: เชื่อมโยงหัวข้อนี้กับบทบาทของ Application Layer ว่าช่วยให้โปรแกรมเครือข่ายสื่อสารกันเข้าใจตรงกัน';
}
function buildThaiReviewSlide(){
 const index=document.getElementById('thaiReviewIndex'), content=document.getElementById('thaiReviewContent'), big=document.getElementById('thaiReviewBigIcon'), vtitle=document.getElementById('thaiReviewVisualTitle'), vnote=document.getElementById('thaiReviewVisualNote'), all=document.getElementById('thaiReviewAllPrint');
 if(!index||!content||!big||!all)return;
 const reviewItems=slides.slice(0,-1).map((_,i)=>guideFor(i));
 let current=0;
 index.innerHTML=reviewItems.map((g,i)=>`<button class="thaiReviewBtn" data-review="${i}"><span class="thaiReviewMiniPic">${thaiReviewIcon(g.title,i)}</span><span class="thaiReviewBtnTitle">${i+1}. ${escapeHTML(g.title)}</span></button>`).join('');
 all.innerHTML=`<h2>คู่มือทบทวนภาษาไทย: Chapter 3 Application Layer</h2>`+reviewItems.map((g,i)=>`<div class="thaiReviewPrintItem"><div class="thaiReviewPrintVisual">${thaiReviewIcon(g.title,i)}</div><h3>Slide ${i+1}: ${escapeHTML(g.title)}</h3><p><b>เนื้อหาอ่าน:</b> ${escapeHTML(g.read)}</p><p><b>บทพูด/คำอธิบาย:</b> ${escapeHTML(g.talk)}</p></div>`).join('');
 function showReview(i){
   current=(i+reviewItems.length)%reviewItems.length;
   const g=reviewItems[current], icon=thaiReviewIcon(g.title,current);
   document.querySelectorAll('.thaiReviewBtn').forEach((b,j)=>b.classList.toggle('active',j===current));
   big.textContent=icon; vtitle.textContent=`Slide ${current+1}: ${g.title}`;
   vnote.textContent=thaiReviewKey(g.title);
   content.innerHTML=`<h3>Slide ${current+1}: ${escapeHTML(g.title)}</h3><div class="thaiReviewKeyBox"><b>ภาพจำ / Key idea</b><p>${escapeHTML(thaiReviewKey(g.title))}</p></div><h4>เนื้อหาภาษาไทยสำหรับอ่านทบทวน</h4>${thaiParagraphs(g.read)}<h4>บทพูดภาษาไทย / คำอธิบายสำหรับสไลด์นี้</h4>${thaiParagraphs(g.talk)}<h4>รูปภาพประกอบที่ควรจำ</h4><p>ใช้ภาพ ${icon} เป็นภาพจำของหัวข้อนี้ และกลับไปดูแผนภาพ/ตัวอย่างบนสไลด์จริงประกอบการอ่าน</p>`;
 }
 index.querySelectorAll('.thaiReviewBtn').forEach(b=>b.addEventListener('click',()=>showReview(Number(b.dataset.review))));
 document.getElementById('thaiReviewPrev')?.addEventListener('click',()=>showReview(current-1));
 document.getElementById('thaiReviewNext')?.addEventListener('click',()=>showReview(current+1));
 document.getElementById('thaiReviewPrint')?.addEventListener('click',()=>{buildPrintNotes();window.print();});
 showReview(0);
}
buildThaiReviewSlide();

function go(n){idx=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===idx));const tocItems=[...document.querySelectorAll('.tocItem')];tocItems.forEach((b,i)=>b.classList.toggle('active',i===idx));tocItems[idx]?.scrollIntoView({block:'nearest'});now.textContent=idx+1;bar.style.width=((idx+1)/slides.length*100)+'%';noteText.textContent=slides[idx].dataset.note||'-';document.querySelectorAll('.topicJump').forEach(b=>{const st=+b.dataset.start,en=+b.dataset.end;b.classList.toggle('active',idx>=st&&idx<=en)});slides[idx].scrollIntoView({block:'nearest',inline:'nearest'});}go(0);
function setFocusMode(on){document.body.classList.toggle('focusMode',on);const btn=document.getElementById('fullscreenBtn');if(btn)btn.textContent=on?'Exit full slide':'Full slide';if(on&&document.documentElement.requestFullscreen){document.documentElement.requestFullscreen().catch(()=>{});}else if(!on&&document.fullscreenElement&&document.exitFullscreen){document.exitFullscreen().catch(()=>{});}setTimeout(()=>go(idx),60)}
document.getElementById('nextBtn').onclick=()=>go(idx+1);document.getElementById('prevBtn').onclick=()=>go(idx-1);document.getElementById('resetBtn').onclick=()=>{go(0);showToast('Lesson reset')};document.getElementById('notesBtn').onclick=()=>document.getElementById('notesPanel').classList.toggle('open');document.getElementById('fullscreenBtn').onclick=()=>setFocusMode(!document.body.classList.contains('focusMode'));document.getElementById('printBtn').onclick=()=>{buildPrintNotes();window.print()};document.getElementById('darkBtn').onclick=()=>{document.body.classList.toggle('dark')};document.getElementById('menuBtn').onclick=()=>document.getElementById('drawer').classList.add('open');document.getElementById('closeMenuBtn').onclick=()=>document.getElementById('drawer').classList.remove('open');if(document.getElementById('thaiPanelClose'))document.getElementById('thaiPanelClose').onclick=()=>document.getElementById('thaiPanel').classList.remove('open');if(document.getElementById('thaiPanel'))document.getElementById('thaiPanel').addEventListener('click',e=>{if(e.target.id==='thaiPanel')e.currentTarget.classList.remove('open')});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('focusMode')});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('thaiPanel')?.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();go(idx+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(idx-1)}if(e.key.toLowerCase()==='d')document.body.classList.toggle('dark');if(e.key.toLowerCase()==='f'){e.preventDefault();setFocusMode(!document.body.classList.contains('focusMode'))}if(e.key==='Escape'&&document.body.classList.contains('focusMode'))setFocusMode(false)});
