function dnsLine(path,active,green=false,bidirectional=false){
  const color = active ? (green ? '#1f9d6a' : '#256fce') : (green ? '#9fd3b3' : '#aab6c3');
  const marker = green ? (active ? 'url(#arrGreen)' : 'url(#arrGreenLite)') : (active ? 'url(#arrBlue)' : 'url(#arrGrey)');
