   ${dnsLine('M478 134 V64 H744', active===3, false, true)}
   ${dnsLine('M605 168 H744', active===4, false, true)}
   ${dnsLine('M448 202 V270 H744', active===5)}
   ${dnsLine('M744 292 H575 V202', active===6)}
   ${active===7 ? '<rect x="412" y="145" width="132" height="46" rx="14" fill="#eef9f2" stroke="#96d8b5" stroke-width="3"/><text x="478" y="165" text-anchor="middle" style="font-family:Segoe UI,Arial,sans-serif;font-size:13px;font-weight:900;fill:#14633e">CACHE RRSET</text><text x="478" y="181" text-anchor="middle" style="font-family:Segoe UI,Arial,sans-serif;font-size:11px;font-weight:800;fill:#14633e">reuse until TTL expires</text>' : ''}
   ${dnsLine('M350 186 H270', active===8)}
   ${dnsLine('M160 202 V260', active===9, true)}

   ${dnsBadge(1,310,149, active===1)}
   ${dnsBadge(2,478,119, active===2)}
   ${dnsBadge(3,612,58, active===3)}
   ${dnsBadge(4,680,150, active===4)}
   ${dnsBadge(5,612,255, active===5)}
   ${dnsBadge(6,612,308, active===6)}
   ${dnsBadge(7,478,218, active===7)}
   ${dnsBadge(8,310,202, active===8)}
   ${dnsBadge(9,185,232, active===9)}
  </svg>`;
}
