// HTTP connection reuse interaction
const persistData={
  non:{title:'Non-persistent HTTP',text:'Follow the sequence: open a connection, request one object, receive one response, close the connection, then repeat for the next object.'},
  persistent:{title:'Persistent HTTP',text:'Follow the sequence: keep one connection open, then reuse it for several request-response exchanges before closing later.'},
  compare:{title:'Compare both behaviors',text:'Non-persistent HTTP repeats connection setup for each object. Persistent HTTP reuses one connection for multiple objects.'}
};
let persistMode='non';
let persistStep=0;
let persistTimer=null;
function persistItemsFor(mode){
  const card=document.getElementById(mode==='persistent'?'persistentCard':'nonPersistCard');
  return card?Array.from(card.querySelectorAll('[data-step]')).sort((a,b)=>(+a.dataset.step)-(+b.dataset.step)):[];
}
function clearPersistFlow(){
  document.querySelectorAll('#nonPersistCard [data-step], #persistentCard [data-step]').forEach(el=>{
    el.classList.remove('stepActive','done');
    el.querySelectorAll('.flowDot').forEach(d=>d.remove());
  });
}
function stopPersist(){
  if(persistTimer){clearInterval(persistTimer);persistTimer=null;}
  const play=document.getElementById('persistPlay');
  if(play)play.textContent='Play';
}
function updatePersistControls(){
  const modeButtons=document.querySelectorAll('#persistSteps .persistBtn');
  modeButtons.forEach(b=>b.classList.toggle('active',b.dataset.persist===persistMode));
  const non=document.getElementById('nonPersistCard');
  const persistent=document.getElementById('persistentCard');
  [non,persistent].forEach(el=>{if(el){el.classList.remove('active','dim')}});
  if(persistMode==='non'){if(non)non.classList.add('active');if(persistent)persistent.classList.add('dim');}
  else if(persistMode==='persistent'){if(persistent)persistent.classList.add('active');if(non)non.classList.add('dim');}
  else {[non,persistent].forEach(el=>{if(el)el.classList.add('active')});}
  const d=persistData[persistMode], info=document.getElementById('persistInfo');
  if(info)info.innerHTML=`<h3>${d.title}</h3><p>${d.text}</p>`;
}
function renderPersistStep(){
  clearPersistFlow();
  updatePersistControls();
  if(persistMode==='compare')return;
  const items=persistItemsFor(persistMode);
  items.forEach((el,i)=>{
    if(i<persistStep)el.classList.add('done');
    if(i===persistStep){
      el.classList.add('stepActive');
      if(el.classList.contains('persistMsgRow')){
        const dot=document.createElement('i');
        dot.className='flowDot';
        dot.setAttribute('aria-hidden','true');
        el.appendChild(dot);
      }
    }
  });
}
function selectPersist(k){
  stopPersist();
  persistMode=k;
  persistStep=0;
  renderPersistStep();
}
function nextPersistStep(){
  if(persistMode==='compare')selectPersist('non');
  const items=persistItemsFor(persistMode);
  if(!items.length)return;
  persistStep=(persistStep+1)%items.length;
  renderPersistStep();
}
function prevPersistStep(){
  if(persistMode==='compare')selectPersist('non');
  const items=persistItemsFor(persistMode);
  if(!items.length)return;
  persistStep=(persistStep-1+items.length)%items.length;
  renderPersistStep();
}
document.querySelectorAll('#persistSteps .persistBtn').forEach(b=>b.addEventListener('click',()=>selectPersist(b.dataset.persist)));
const persistNext=document.getElementById('persistNext'); if(persistNext)persistNext.addEventListener('click',nextPersistStep);
const persistPrev=document.getElementById('persistPrev'); if(persistPrev)persistPrev.addEventListener('click',prevPersistStep);
const persistReset=document.getElementById('persistReset'); if(persistReset)persistReset.addEventListener('click',()=>{stopPersist();persistStep=0;renderPersistStep();});
const persistPlay=document.getElementById('persistPlay'); if(persistPlay)persistPlay.addEventListener('click',()=>{
  if(persistTimer){stopPersist();return;}
  if(persistMode==='compare')persistMode='non';
  persistPlay.textContent='Pause';
  renderPersistStep();
  persistTimer=setInterval(nextPersistStep,1200);
});
if(document.getElementById('persistSteps'))selectPersist('non');

