  const ftpData={
    control:{title:'Persistent control connection',text:'FTP opens a TCP control connection to server port 21. Commands and 3-digit replies travel here; it remains open while the session is active.',meta:['TCP 21','USER, PASS, CWD, QUIT','Replies: 220, 230, 331'],cmd:['USER student','PASS ********  → 230 Login successful','PWD / CWD / QUIT on control'],data:['No file bytes on control channel','Data is separate'],pulse:[465,107]},
