    list:{title:'Directory listing uses a data connection',text:'LIST is a command on the control connection, but the directory listing itself is transmitted over a temporary data connection.',meta:['LIST / NLST','150 opening data','226 transfer complete'],cmd:['PASV → server passive port','LIST','150 opening ASCII mode data'],data:['Directory names flow on data channel','226 complete'],pulse:[465,277]},
