    relay:{title:'SMTP relay is store-and-forward',text:'Mail servers relay messages using SMTP, usually over port 25. If the next server is unavailable, the message may stay in a queue and retry later.',meta:['MTA → MTA','Port 25','queue + retry'],line:'MAIL FROM / RCPT TO / DATA across server-to-server SMTP',pulse:[492,128]},
