})();

(function(){
  const stateDataV2={
    stateless:{title:'Stateless HTTP: no built-in memory',meta:['independent request','independent response','no automatic login memory'],text:'HTTP does not remember previous requests by itself. A request must include the information needed for the server to understand and process it.',req:'GET /profile HTTP/1.1',res:'200 OK — response for this request',label:'No automatic memory between requests',rule:'Important to learn: without extra state mechanisms, the next request looks like a new request.',pulse:[380,126]},
    cookie:{title:'Cookie + server-side session',meta:['Set-Cookie','Cookie header','server session store'],text:'After login, the server can set a cookie such as sid=abc123. Later requests send that cookie, and the server uses it to find the user session.',req:'Cookie: sid=abc123',res:'Server lookup: sid → user/cart/preferences',label:'Cookie carries an ID; server remembers the state',rule:'Important to learn: cookies and sessions explain login, shopping carts, preferences, and CSRF protection.',pulse:[623,242]},
    token:{title:'Bearer token for APIs',meta:['Authorization header','Bearer / JWT','expiry + scope'],text:'Token-based APIs put proof of identity or permission in each request, commonly with Authorization: Bearer <token>. The server validates the token before responding.',req:'Authorization: Bearer eyJhbGciOi...',res:'200 OK or 401 Unauthorized',label:'Every API request carries authorization proof',rule:'Important to learn: tokens are common in mobile apps, single-page apps, and API services.',pulse:[380,242]},
