  selectStateV2('stateless');

  const ftpDataV2={
    control:{title:'Control connection: command channel',meta:['TCP 21','persistent during session','3-digit replies'],text:'The client opens a TCP connection to server port 21. Commands such as USER, PASS, CWD, LIST, RETR, STOR and replies such as 220, 331, 230, 150, 226 travel here.',cmd:['USER student  → 331 password required','PASS ******** → 230 logged in','CWD /pub or QUIT on control'],data:['No file bytes on control connection','Only commands and replies'],pulse:[465,104]},
    login:{title:'Login and representation setup',meta:['USER/PASS','TYPE I binary','PASV or PORT'],text:'After authentication, the client normally selects binary mode with TYPE I and then chooses how the next data connection will be created: passive mode (PASV) or active mode (PORT).',cmd:['USER student','PASS ******** → 230 logged in','TYPE I; then PASV or PORT'],data:['Ready for separate data channel','Directory/file bytes still not here'],pulse:[465,121]},
    passive:{title:'Passive mode: client connects to server data port',meta:['PASV','NAT-friendly','server high port'],text:'In passive mode, the server replies with an IP and data port. The client initiates the data TCP connection to that server port, which is why passive mode is common behind firewalls/NAT.',cmd:['PASV','227 Entering Passive Mode (server:port)','Client opens TCP → server data port'],data:['Data channel opened by client','LIST/RETR/STOR can now transfer'],pulse:[350,230]},
