  const emailDataV2={
    compose:{title:'1. Compose the email in the sender mail app',meta:['MUA','headers','MIME attachments'],text:'The sender uses a Mail User Agent (MUA). The app prepares the header, body, and optional MIME attachments before any network transfer happens.',line:'Message format: From / To / Subject / Date + body + MIME parts',pulse:[117,84]},
