(function(){
 const socketModes={
  tcp:{title:'TCP: establish a connection, then exchange data',steps:[['Create the message','The application prepares a request or other application data.'],['Choose the endpoint','The socket uses the server IP address and service port.'],['Connect first','TCP establishes a logical connection before application data is exchanged.'],['Exchange data','The client and server send and receive a reliable byte stream.'],['Finish','The connection is closed when the conversation is complete.']],lane:[['Client process','connects to server endpoint','Server process'],['Client process','application request bytes →','Server process'],['Client process','← application response bytes','Server process']],note:'For this chapter, “connect first, then exchange data” is enough. TCP handshakes, reliability, sequence numbers, and API calls are studied later.'},
  udp:{title:'UDP: send a separate datagram without connection setup',steps:[['Create the message','The application prepares one message.'],['Choose the endpoint','The socket uses the destination IP address and port.'],['Send directly','UDP sends the message as a datagram without first establishing a transport connection.'],['Receive a reply if needed','The receiver may send another independent datagram back.']],lane:[['Client process','datagram to server IP:port →','Server process'],['Client process','← optional reply datagram','Server process'],['Each message','remains a separate datagram','No connection setup']],note:'For this chapter, “send separate messages directly” is enough. Loss, ordering, checksums, and UDP programming details are studied later.'},
  compare:{title:'What students need to remember now',steps:[['Both use sockets','Applications access transport services through the socket interface.'],['Both use endpoints','The destination is identified by transport protocol, IP address, and port.'],['TCP','Connect first; then exchange a reliable byte stream.'],['UDP','No connection setup; exchange separate datagrams.']],lane:[['TCP','connection first → byte stream','Web, email, SSH'],['UDP','datagrams without setup','DNS, DHCP, NTP'],['Application protocol','defines message meaning','Transport carries it']],note:'The application chooses the service it needs. This slide is only a preview—not a full Transport Layer lesson.'}
 };
 function setSocketMode(k){const d=socketModes[k];document.querySelectorAll('#socketModeTabs button').forEach(b=>b.classList.toggle('active',b.dataset.socketmode===k));const st=document.getElementById('socketModeSteps'),la=document.getElementById('socketModeLane');if(st)st.innerHTML=d.steps.map((x,i)=>`<div class="socketModeStep"><b>${i+1}</b><div><strong>${x[0]}</strong><span>${x[1]}</span></div></div>`).join('');if(document.getElementById('socketModeTitle'))document.getElementById('socketModeTitle').textContent=d.title;if(la)la.innerHTML=d.lane.map(x=>`<div class="laneRow"><div class="laneRole">${x[0]}</div><div class="laneMsg">${x[1]}</div><div class="laneRole">${x[2]}</div></div>`).join('');if(document.getElementById('socketModeNote'))document.getElementById('socketModeNote').textContent=d.note;}
 document.querySelectorAll('#socketModeTabs button').forEach(b=>b.addEventListener('click',()=>setSocketMode(b.dataset.socketmode)));if(document.getElementById('socketModeTabs'))setSocketMode('tcp');

 const httpsPaths={tcp:{title:'HTTPS with HTTP/1.1 or HTTP/2',layers:[['appLayer','HTTP request / response'],['tls','TLS records: encryption, integrity, certificate authentication'],['transport','TCP connection to server port 443'],['network','IP packets routed between hosts']],text:'HTTP/1.1 and HTTP/2 commonly run inside TLS over TCP. HTTP/2 can multiplex streams, but all streams still share the same TCP connection.'},quic:{title:'HTTPS with HTTP/3',layers:[['appLayer','HTTP/3 request / response'],['tls','QUIC transport with TLS 1.3 integrated into its handshake'],['transport','UDP datagrams to server port 443'],['network','IP packets routed between hosts']],text:'HTTP/3 runs over QUIC rather than TCP. QUIC provides reliable independent streams, congestion control, and security while using UDP as its network-facing transport.'}};
 function setHttpsPath(k){const d=httpsPaths[k];document.querySelectorAll('#httpsPathTabs button').forEach(b=>b.classList.toggle('active',b.dataset.httpspath===k));if(document.getElementById('httpsPathTitle'))document.getElementById('httpsPathTitle').textContent=d.title;if(document.getElementById('httpsStackRev'))document.getElementById('httpsStackRev').innerHTML=d.layers.map(x=>`<div class="httpsStackLayer ${x[0]}">${x[1]}</div>`).join('');if(document.getElementById('httpsPathExplanation'))document.getElementById('httpsPathExplanation').textContent=d.text;}
 document.querySelectorAll('#httpsPathTabs button').forEach(b=>b.addEventListener('click',()=>setHttpsPath(b.dataset.httpspath)));if(document.getElementById('httpsPathTabs'))setHttpsPath('tcp');

 if(typeof statusData!=='undefined')statusData['1xx']={title:'1xx Informational',text:'The server has received the request and sends an interim response while processing continues or the protocol changes.',examples:['100 Continue — client may send the request body','101 Switching Protocols — protocol change accepted','103 Early Hints — preload linked resources'],action:'Client behavior: continue the exchange; do not treat the interim response as the final result.'};
