(function(){
  const states={
    non:{card:document.getElementById('nonPersistCard'),step:-1,timer:null},
    persistent:{card:document.getElementById('persistentCard'),step:-1,timer:null}
  };
  function items(key){
    const card=states[key].card;
    return card?Array.from(card.querySelectorAll('[data-step]')).sort((a,b)=>(+a.dataset.step)-(+b.dataset.step)):[];
  }
  function clearCard(key){
    if(!states[key].card)return;
    states[key].card.querySelectorAll('[data-step]').forEach(el=>{
      el.classList.remove('stepActive','done');
      el.querySelectorAll('.flowDot').forEach(d=>d.remove());
    });
  }
  function render(key){
    clearCard(key);
    const list=items(key);
    list.forEach((el,i)=>{
      if(i<states[key].step)el.classList.add('done');
      if(i===states[key].step){
        el.classList.add('stepActive');
        if(el.classList.contains('persistMsgRow')){
          const dot=document.createElement('i');
          dot.className='flowDot';
          dot.setAttribute('aria-hidden','true');
          el.appendChild(dot);
        }
      }
    });
  }
  function stop(key){
    if(states[key].timer){clearInterval(states[key].timer);states[key].timer=null;}
    const btn=document.querySelector('.cardMiniControls[data-control-card="'+key+'"] [data-action="play"]');
    if(btn)btn.textContent='Play';
  }
  function next(key){
    const list=items(key); if(!list.length)return;
    states[key].step=(states[key].step+1)%list.length;
    render(key);
  }
  function prev(key){
    const list=items(key); if(!list.length)return;
    if(states[key].step<0){states[key].step=list.length-1;}else{states[key].step=(states[key].step-1+list.length)%list.length;}
    render(key);
  }
  document.querySelectorAll('.cardMiniControls[data-control-card]').forEach(group=>{
    const key=group.dataset.controlCard;
    group.querySelectorAll('button[data-action]').forEach(btn=>btn.addEventListener('click',()=>{
      const action=btn.dataset.action;
      if(action==='next'){stop(key);next(key);}
      else if(action==='prev'){stop(key);prev(key);}
      else if(action==='reset'){stop(key);states[key].step=-1;render(key);}
      else if(action==='play'){
        if(states[key].timer){stop(key);return;}
        btn.textContent='Pause';
        if(states[key].step<0)states[key].step=0;
        render(key);
        states[key].timer=setInterval(()=>next(key),1150);
      }
    }));
  });
  render('non');
  render('persistent');
})();

(function(){
  const modal=document.getElementById('httpCaptureModal');
  const modalImg=document.getElementById('httpCaptureModalImg');
  const modalTitle=document.getElementById('httpCaptureModalTitle');
  const closeBtn=document.getElementById('httpCaptureClose');
  if(!modal||!modalImg||!modalTitle)return;
  function openCapture(button){
    const img=button.querySelector('img');
    if(!img)return;
    modalImg.src=img.src;
    modalImg.alt=img.alt;
    modalTitle.textContent=img.alt.replace(/^Wireshark HTTP screenshot [A-E]:\s*/,'').replace(/^Wireshark HTTP packet list showing /,'HTTP packet list: ');
    modal.classList.add('open');
    closeBtn?.focus();
  }
  function closeCapture(){modal.classList.remove('open');modalImg.removeAttribute('src');}
  document.querySelectorAll('.captureOverviewBtn,.captureShotBtn').forEach(btn=>btn.addEventListener('click',()=>openCapture(btn)));
  closeBtn?.addEventListener('click',closeCapture);
  modal.addEventListener('click',e=>{if(e.target===modal)closeCapture();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeCapture();});
})();
